ex_trace_deque.py.src:
from collections import deque

q = deque()
for step in ["Ada", "Bo", "serve", "Cy", "serve", "serve"]:
    if step == "serve":
        who = q.popleft()
    else:
        q.append(step)
        who = "-"
    print(step, who, len(q))

